-- Privacy-preserving confirmed investor-request conversion attribution.
-- Each recorded conversion is generated by a successfully saved real package request.
-- Browser-reported origin is an ASSISTED attribution hint, never a verified referrer.
ALTER TABLE public.package_requests
 ADD COLUMN IF NOT EXISTS origin_path text NULL;
ALTER TABLE public.package_requests
 DROP CONSTRAINT IF EXISTS package_requests_origin_path_safe;
ALTER TABLE public.package_requests
 ADD CONSTRAINT package_requests_origin_path_safe
 CHECK (origin_path IS NULL OR (
   length(origin_path) BETWEEN 1 AND 180 AND
   origin_path ~ '^/(en/|zh/)?(insights/[a-z0-9]+(-[a-z0-9]+)*|services/(company-formation|misa-license|corporate-banking|contract-drafting|premium-residency|investment-funds)|packages)?/?$'
 ));

CREATE TABLE IF NOT EXISTS public.impact_lead_events (
 request_id uuid PRIMARY KEY REFERENCES public.package_requests(id) ON DELETE RESTRICT,
 occurred_at timestamptz NOT NULL,
 source_path text NOT NULL,
 attribution text NOT NULL CHECK(attribution IN ('client_reported','form_page')),
 locale text NOT NULL CHECK(locale IN ('ar','en','zh')),
 kind text NOT NULL DEFAULT 'package_request_saved'
   CHECK(kind='package_request_saved')
);
CREATE INDEX IF NOT EXISTS impact_lead_events_occurred_at_idx
 ON public.impact_lead_events(occurred_at DESC);
CREATE INDEX IF NOT EXISTS impact_lead_events_path_at_idx
 ON public.impact_lead_events(source_path,occurred_at DESC);
ALTER TABLE public.impact_lead_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.impact_lead_events FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT ON public.impact_lead_events TO service_role;

CREATE OR REPLACE FUNCTION public.record_package_request_impact()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 INSERT INTO public.impact_lead_events(request_id,occurred_at,source_path,attribution,locale)
 VALUES (NEW.id,NEW.created_at,
   COALESCE(NEW.origin_path,CASE WHEN NEW.locale='ar' THEN '/packages'
                                 ELSE '/'||NEW.locale||'/packages' END),
   CASE WHEN NEW.origin_path IS NULL THEN 'form_page' ELSE 'client_reported' END,
   NEW.locale)
 ON CONFLICT (request_id) DO NOTHING;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.record_package_request_impact() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS package_request_impact_insert ON public.package_requests;
CREATE TRIGGER package_request_impact_insert
 AFTER INSERT ON public.package_requests FOR EACH ROW
 EXECUTE FUNCTION public.record_package_request_impact();
-- No historical event backfill. Unknown earlier acquisition paths remain unknown.
